import pathlib,json
Q=pathlib.Path.cwd().parent/'review-packet'
for name,needles in {
 'observation-clauses.json':['"id": "CONFIG_VALIDATION"','"id": "RUNNER_SELECT"','"id": "RUNNER_EXECUTABLE_SELECTORS"','"id": "ENV_FACTS"','"id": "ACL_RUNNER_ENTRY"'],
 'semantic-proposals.json':['"symbol": "Config.probeTimeoutMs"','"symbol": "SandboxInternals.probeWindowsAcl"'],
 'procedures.json':['"id": "SBX08"','"id": "SBX09"','"id": "CONFIG_VALIDATION"','"id": "RUNNER_SELECT"']}.items():
 lines=(Q/name).read_text().splitlines();print(name)
 for needle in needles:
  loc=[i+1 for i,l in enumerate(lines) if needle in l]
  print(needle,loc)
  if name=='observation-clauses.json' and needle in ['"id": "CONFIG_VALIDATION"','"id": "RUNNER_SELECT"']:
   for n in range(loc[0],min(loc[0]+40,len(lines)+1)): print(f'{n}: {lines[n-1]}')
p=json.loads((Q/'semantic-proposals.json').read_text())
for name in ['Config.probeTimeoutMs','SandboxInternals.probeWindowsAcl']:
 e=next(x for x in p if x['catalogContract']['symbol']==name);print('BINDING',name,e['leafId'])

